    47→
    48→  public ExtensionNode(
    49→      final Bytes location,
    50→      final Bytes path,
    51→      final Node<V> child,
    52→      final NodeFactory<V> nodeFactory) {
    53→    assert (path.size() > 0);
    54→    assert (path.get(path.size() - 1) != CompactEncoding.LEAF_TERMINATOR)
    55→        : "Extension path ends in a leaf terminator";
    56→    this.location = Optional.ofNullable(location);
    57→    this.path = path;
    58→    this.child = child;
    59→    this.nodeFactory = nodeFactory;
    60→  }
    61→
    62→  public ExtensionNode(final Bytes path, final Node<V> child, final NodeFactory<V> nodeFactory) {
    63→    assert (path.size() > 0);
    64→    assert (path.get(path.size() - 1) != CompactEncoding.LEAF_TERMINATOR)
    65→        : "Extension path ends in a leaf terminator";
    66→    this.location = Optional.empty();
    67→    this.path = path;
    68→    this.child = child;
    69→    this.nodeFactory = nodeFactory;
    70→  }
    71→
    72→  @Override
    73→  public Node<V> accept(final PathNodeVisitor<V> visitor, final Bytes path) {
    74→    return visitor.visit(this, path);
    75→  }
    76→
    77→  @Override
    78→  public void accept(final NodeVisitor<V> visitor) {
    79→    visitor.visit(this);
    80→  }
    81→
    82→  @Override
    83→  public void accept(final Bytes location, final LocationNodeVisitor<V> visitor) {
    84→    visitor.visit(location, this);
    85→  }
    86→
    87→  @Override
    88→  public Optional<Bytes> getLocation() {
    89→    return location;
    90→  }
    91→
    92→  @Override
    93→  public Bytes getPath() {
    94→    return path;
    95→  }
    96→
    97→  @Override
    98→  public Optional<V> getValue() {
    99→    return Optional.empty();
   100→  }

