   206→  // As per https://eips.ethereum.org/EIPS/eip-2200
   207→  public long calculateStorageRefundAmount(
   208→      final UInt256 newValue,
   209→      final Supplier<UInt256> currentValue,
   210→      final Supplier<UInt256> originalValue) {
   211→
   212→    final UInt256 localCurrentValue = currentValue.get();
   213→    if (localCurrentValue.equals(newValue)) {
   214→      return 0L;
   215→    } else {
   216→      final UInt256 localOriginalValue = originalValue.get();
   217→      if (localOriginalValue.equals(localCurrentValue)) {
   218→        if (localOriginalValue.isZero()) {
   219→          return 0L;
   220→        } else if (newValue.isZero()) {
   221→          return SSTORE_CLEARS_SCHEDULE;
   222→        } else {
   223→          return 0L;
   224→        }
   225→      } else {
   226→        long refund = 0L;
   227→        if (!localOriginalValue.isZero()) {
   228→          if (localCurrentValue.isZero()) {
   229→            refund = NEGATIVE_SSTORE_CLEARS_SCHEDULE;
   230→          } else if (newValue.isZero()) {
   231→            refund = SSTORE_CLEARS_SCHEDULE;
   232→          }
   233→        }
   234→
   235→        if (localOriginalValue.equals(newValue)) {
   236→          refund =
   237→              refund
   238→                  + (localOriginalValue.isZero()
   239→                      ? SSTORE_SET_GAS_LESS_SLOAD_GAS
   240→                      : SSTORE_RESET_GAS_LESS_SLOAD_GAS);
   241→        }
   242→        return refund;
   243→      }
   244→    }
   245→  }
