    23→public class CommitVisitor<V> implements LocationNodeVisitor<V> {
    24→
    25→  protected final NodeUpdater nodeUpdater;
    26→
    27→  public CommitVisitor(final NodeUpdater nodeUpdater) {
    28→    this.nodeUpdater = nodeUpdater;
    29→  }
    30→
    31→  @Override
    32→  public void visit(final Bytes location, final ExtensionNode<V> extensionNode) {
    33→    if (!extensionNode.isDirty()) {
    34→      return;
    35→    }
    36→
    37→    final Node<V> child = extensionNode.getChild();
    38→    if (child.isDirty()) {
    39→      child.accept(Bytes.concatenate(location, extensionNode.getPath()), this);
    40→    }
    41→
    42→    maybeStoreNode(location, extensionNode);
    43→  }
    44→
    45→  @Override
    46→  public void visit(final Bytes location, final BranchNode<V> branchNode) {
    47→    if (!branchNode.isDirty()) {
    48→      return;
    49→    }
    50→
    51→    for (int i = 0; i < branchNode.maxChild(); ++i) {
    52→      Bytes index = Bytes.of(i);
    53→      final Node<V> child = branchNode.child((byte) i);
    54→      if (child.isDirty()) {
    55→        child.accept(Bytes.concatenate(location, index), this);
    56→      }
    57→    }
    58→
    59→    maybeStoreNode(location, branchNode);
    60→  }
    61→
    62→  @Override
    63→  public void visit(final Bytes location, final LeafNode<V> leafNode) {
    64→    if (!leafNode.isDirty()) {
    65→      return;
    66→    }
    67→
    68→    maybeStoreNode(location, leafNode);
    69→  }
    70→
    71→  @Override
    72→  public void visit(final Bytes location, final NullNode<V> nullNode) {}
    73→
    74→  public void maybeStoreNode(final Bytes location, final Node<V> node) {
    75→    final Bytes nodeRLP = node.getEncodedBytes();
    76→    if (nodeRLP.size() >= 32) {
    77→      this.nodeUpdater.store(location, node.getHash(), nodeRLP);
    78→    }
    79→  }
    80→}

