    38→ *
    39→ * @param <V> The type of values stored by this trie.
    40→ */
    41→public abstract class StoredMerkleTrie<K extends Bytes, V> implements MerkleTrie<K, V> {
    42→
    43→  protected final NodeFactory<V> nodeFactory;
    44→
    45→  protected Node<V> root;
