    61→   *     storage}.
    62→   * @param rootLocation The initial root location for the trie
    63→   */
    64→  public StoredMerkleTrie(
    65→      final NodeFactory<V> nodeFactory, final Bytes32 rootHash, final Bytes rootLocation) {
    66→    this.nodeFactory = nodeFactory;
    67→    this.root =
    68→        rootHash.equals(EMPTY_TRIE_NODE_HASH)
    69→            ? NullNode.instance()
    70→            : new StoredNode<>(nodeFactory, rootLocation, rootHash);
    71→  }
    72→
    73→  /**
